"""HIA-owned Code state admission, labels, registers and final fixup ordering.

The bridge performs requested primitive Python object operations and preserves
the actual public mutable objects. It holds no duplicate native labels/fixups
map. Instruction admission outside these six operations remains a separate
owner; emitted rel32 bytes are supplied by the selected HIA byte encoder.
"""
from __future__ import annotations

from collections import Counter
import ctypes
from functools import lru_cache
import struct
import sys

from .hia_json_preflight_native import NativeHiaJsonImage, _installed_json_image, _source_resource_path
from .hia_machine_transport import _private_zeroed_buffer, _code_call_names
from .hia_exception_delivery import ExceptionDelivery

SOURCE = _source_resource_path('examples/hia_bootstrap/machine_state.hiaasm')
SCHEMA = 'hepta.hia.machine-state-native.v1'
SELECTOR = 'HEPTA_HIA_MACHINE_STATE_MANIFEST'
MAGIC = int.from_bytes(b'HIACST01', 'little')
MASK = (1 << 64) - 1
MODES = ('initialize', 'emit', 'label', 'finalize', 'offset', 'register')
_RELEASED = object()


class MachineStateSession:
    """One immutable entry request, private continuation and one-shot effects."""
    def __init__(self, image, receiver, mode, *arguments):
        if type(mode) is not int or not 1 <= mode <= 6 or len(arguments) > 3:
            raise ValueError('invalid native Code state operation')
        self.image, self.receiver, self.mode = image, receiver, mode
        # Each live handle is one native-owned reference. Equal/identical
        # objects may have distinct handles when two original operand slots
        # independently own them. HIA alone decides when each slot is retired.
        self.values = [_RELEASED]
        self.free_handles = []
        self.workspace = _private_zeroed_buffer(2048)
        self.output = ctypes.create_string_buffer(b'\xa5' * 8, 8)
        args = arguments + (None,) * (3 - len(arguments))
        self.none = self.register(None)
        self.packet = struct.pack('<10Q', MAGIC, 0, 0, mode, self.register(receiver),
                                  *(self.register(v) for v in args), self.none, 0)
        self.finished = False
        self.pending = False
        self.prepared = True
        self._prepared_packet = self.packet
        self._issued = None
        self._frame = None
        self._busy = False
        self._closed = False

    def register(self, value):
        if value is None and hasattr(self, 'none'):
            return self.none
        if self.free_handles:
            handle = self.free_handles.pop()
            self.values[handle] = value
        else:
            handle = len(self.values)
            self.values.append(value)
        return handle

    def value(self, handle):
        if (type(handle) is not int or not 0 < handle < len(self.values)
                or self.values[handle] is _RELEASED):
            raise RuntimeError('native Code state requested an unknown object handle')
        return self.values[handle]

    def _retire(self, handle):
        if handle != self.none:
            self.value(handle)
            # Publish the empty slot before DECREF can run foreign __del__.
            self.values[handle] = _RELEASED
            self.free_handles.append(handle)

    def _release_plan(self, frame):
        before_count, = struct.unpack_from('<Q', frame, 640)
        after_count, = struct.unpack_from('<Q', frame, 776)
        result, = struct.unpack_from('<Q', frame, 912)
        if before_count > 16 or after_count > 16 or result not in (0, 1):
            raise RuntimeError('native Code reference plan shape differs')
        before = struct.unpack_from('<' + 'Q' * before_count, frame, 648)
        after = struct.unpack_from('<' + 'Q' * after_count, frame, 784)
        if len(set(before + after)) != len(before + after):
            raise RuntimeError('native Code reference plan repeats an owning slot')
        for handle in before + after:
            self.value(handle)
        return before, after, result

    def _retire_all(self, handles):
        for handle in handles:
            self._retire(handle)

    def _abort(self):
        self.finished = True
        self.pending = False
        self.prepared = False
        self._prepared_packet = None
        self._issued = None
        self._frame = None
        self._busy = False
        self._closed = True

    def close(self, *, release=True):
        self._abort()
        if release:
            self.values.clear()
            self.free_handles.clear()

    def _literal(self, offset, count):
        if offset != 1024 or not 0 < count <= 192:
            raise RuntimeError('native Code state literal span differs')
        text = self._frame[offset:offset + count].decode('utf-8')
        # CPython's original identifier constants/attribute names are interned.
        # Keep those literal objects canonical for foreign equality observers.
        return sys.intern(text) if text.isidentifier() else text

    def step(self, packet=None):
        if self.finished or self._closed or self._busy:
            raise RuntimeError('native Code state continuation is terminal')
        if packet is None and not self.prepared:
            raise RuntimeError('native Code state observation has not been acknowledged')
        try:
            raw = self.packet if packet is None else packet
            if type(raw) is not bytes:
                raise TypeError('native Code state packet must be exact bytes')
            diagnostic = not self.prepared
            if not diagnostic and raw != self._prepared_packet:
                raise RuntimeError('native Code acknowledgement differs from issued result')
            # An explicit unacknowledged packet remains a diagnostic native
            # ABI refusal probe. It can never publish a callback permission.
            self._busy = True
            self.pending = False
            self.prepared = False
            self._prepared_packet = None
            self._issued = None
            status = self.image._entry(raw, len(raw), self.output, len(self.output),
                                       self.workspace, len(self.workspace))
            if type(status) is not int:
                raise RuntimeError('native Code ABI status is not an exact integer')
            frame, output = bytes(self.workspace), bytes(self.output)
            self.image.transitions[self.mode] += 1
            if (bytes(self.workspace) != frame or bytes(self.output) != output
                    or type(self.packet) is not bytes
                    or (not diagnostic and self.packet != raw)):
                raise RuntimeError('native Code result changed during publication')
            if diagnostic:
                self._abort()
                if status != 0xfffffffd:
                    raise RuntimeError('unacknowledged native Code continuation was accepted')
                return status
            if status == 1:
                self._release_plan(frame)
                self._issued = (frame, output, self.packet)
                self.pending = True
            else:
                self.finished = True
                if status == 0:
                    before, after, result = self._release_plan(frame)
                    if result:
                        raise RuntimeError('terminal native Code frame requests a callback result')
                    self._retire_all(before)
                    self._retire_all(after)
                    self._issued = (frame, output, self.packet)
            self._busy = False
            return status
        except BaseException:
            # A native transition may already have happened. Diagnostic
            # bookkeeping must not leave a resumable or repeatable session.
            self._abort()
            raise

    def result(self):
        try:
            issued = self._issued
            if (not self.finished or self._closed or self._busy or issued is None
                    or bytes(self.workspace) != issued[0]
                    or bytes(self.output) != issued[1]
                    or type(self.packet) is not bytes or self.packet != issued[2]):
                raise RuntimeError('native Code terminal result is not the issued frame')
            self._issued = None
            handle, = struct.unpack('<Q', issued[1])
            return self.value(handle)
        except BaseException:
            self._abort()
            raise

    def observe(self):
        if self.finished or self._closed or self._busy or not self.pending:
            raise RuntimeError('native Code state has no unconsumed observation')
        try:
            issued = self._issued
            if (issued is None or bytes(self.workspace) != issued[0]
                    or bytes(self.output) != issued[1]
                    or type(self.packet) is not bytes or self.packet != issued[2]):
                raise RuntimeError('native Code issued observation frame changed')
            before, after, discard = self._release_plan(issued[0])
            # Consume the exact machine-issued permission before any foreign
            # operation, including destructor effects from reference release.
            self._busy = True
            self.pending = False
            self._issued = None
            self._frame = issued[0]
            self._retire_all(before)
            succeeded, observed = self._observe_captured()
            try:
                # The fixed catcher has left its exception handler. Release
                # only the slots already authorized by this issued HIA frame,
                # with the caller's original handled-exception state active.
                self._retire_all(after)
                if not succeeded:
                    self.image._exception_delivery.deliver(observed)
                    raise RuntimeError('native Code exception delivery returned')
                reply = observed
            finally:
                # An error traceback must not retain an error -> this local
                # -> traceback cycle after the original instance is delivered.
                observed = None
            if discard:
                self._retire(struct.unpack_from('<Q', reply, 32)[0])
            self.packet = reply
            self._prepared_packet = reply
            self._frame = None
            self.prepared = True
            self._busy = False
            return self.packet
        except BaseException:
            self._abort()
            raise

    def _observe_captured(self):
        try:
            return True, self._observe()
        except BaseException as error:
            # Returning leaves the handler before operand reference release.
            # This is fixed foreign transport, not a generator or policy path.
            return False, error

    def _observe(self):
        from .hia_machine_x64 import MachineEncodingError
        opcode, sequence = struct.unpack_from('<2Q', self._frame, 8)
        a, b, c, d = struct.unpack_from('<4Q', self._frame, 512)
        value, reg = self.value, self.register
        x = y = z = t = 0
        self.image.observations[opcode] += 1
        if opcode == 1:
            kind = type(value(a))
            # This is an exact primitive type tag, not operand admission.
            kinds = (type(None), bool, int, str, bytes, bytearray, dict, list, tuple)
            x = next((i for i, builtin in enumerate(kinds) if kind is builtin), 9)
            y = reg(kind)
        elif opcode == 2:
            size = len(value(a))
            x, y = reg(size), size
        elif opcode == 3:
            x = reg(getattr(value(a), self._literal(b, c)))
        elif opcode == 4:
            setattr(value(a), self._literal(c, d), value(b))
        elif opcode == 5:
            x = reg(self._literal(a, b))
        elif opcode == 6:
            x = reg({})
        elif opcode == 7:
            x = reg([])
        elif opcode == 8:
            x = reg(bytearray())
        elif opcode == 9:
            x = reg(bytes(value(a)))
        elif opcode == 10:
            x = reg(dict(value(a)))
        elif opcode == 11:
            x = reg(set(value(a)))
        elif opcode == 12:
            x = reg({value(a), value(b)})
        elif opcode == 13:
            x = int(bool(value(a) != value(b)))
        elif opcode == 14:
            x = reg(iter(value(a)))
        elif opcode == 15:
            try:
                item = next(value(a))
            except StopIteration:
                x, y = self.none, 0
            else:
                x, y = reg(item), 1
        elif opcode == 16:
            first, second = value(a)
            x, y = reg(first), reg(second)
        elif opcode == 17:
            x = int(value(b) in value(a))
        elif opcode == 18:
            x = reg(value(a)[value(b)])
        elif opcode == 19:
            value(a)[value(b)] = value(c)
        elif opcode == 20:
            x = reg(value(a) + value(b))
        elif opcode == 21:
            x = reg(value(a) - value(b))
        elif opcode == 22:
            value(a)[value(b):value(c)] = value(d)
        elif opcode == 23:
            x = reg(value(a)())
        elif opcode == 24:
            x = reg(value(a)(value(b)))
        elif opcode == 25:
            x = reg(value(a)(value(b), value(c)))
        elif opcode == 26:
            value(a).append(value(b))
        elif opcode == 27:
            x = reg(a)
        elif opcode == 28:
            # HIA has already admitted the exact integer and signed width.
            # The existing byte bridge invokes the HIA rel32 command.
            x = reg(self.receiver._bytes('rel32', value=value(a)))
        elif opcode == 29:
            raise MachineEncodingError(value(a))
        elif opcode == 30:
            text = value(a)
            if type(text) is not str:
                raise RuntimeError('native Code state string observation type differs')
            x = len(text)
            points = tuple(ord(ch) for ch in text[:3]) + (0, 0, 0)
            y, z, t = points[:3]
        elif opcode == 31:
            number = value(a)
            if type(number) is not int:
                raise RuntimeError('native Code state integer observation type differs')
            x, y, z = number & MASK, int(number < 0), number.bit_length()
        elif opcode == 32:
            x = reg((value(a), value(b)))
        elif opcode == 33:
            x = reg({value(a): value(b), value(c): value(d)})
        elif opcode == 34:
            x = reg(bytearray(value(a)))
        elif opcode == 35:
            if b not in (4, 5):
                raise RuntimeError('native Code state requested an unknown type literal')
            candidate = bytes if b == 4 else bytearray
            observed = value(a)
            # Tuple membership compares the candidate first and includes the
            # foreign metaclass's reflected equality and truth observation.
            x = int(candidate is observed or bool(candidate == observed))
        else:
            raise RuntimeError('unknown native Code state observation opcode')
        return struct.pack('<10Q', MAGIC, opcode, sequence, 0, x, y, z, t, 0, 0)


class NativeMachineState(NativeHiaJsonImage):
    def __init__(self, image, expected_sha256):
        super().__init__(image, expected_sha256)
        self.calls = Counter()
        self.transitions = Counter()
        self.observations = Counter()
        # Admit and emit the physical delivery mechanism before any Code
        # callback can run. Its immutable mapping is shared; calls own frames.
        self._exception_delivery = ExceptionDelivery.from_hia(self)

    def run(self, receiver, mode, *arguments):
        session = MachineStateSession(self, receiver, mode, *arguments)
        try:
            self.calls[MODES[mode - 1]] += 1
            status = session.step()
            while status == 1:
                session.observe()
                status = session.step()
            if status != 0:
                raise RuntimeError('native Code state continuation refused: ' + hex(status))
            return session.result()
        finally:
            # A retained foreign exception traceback keeps the still-live
            # original local slots, but its context is permanently terminal.
            session.close(release=sys.exc_info()[0] is None)


@lru_cache(maxsize=3)
def selected_state_code_class(encoding, state):
    from .hia_machine_encoding_native import NativeEncodedCode

    class SelectedStateCode(NativeEncodedCode):
        def __init__(self, *, scratch_registers=None,
                     move_immediate='movabs', alu_immediate='imm32'):
            state.run(self, 1, scratch_registers, move_immediate, alu_immediate)
            self.encoding = encoding

        def emit(self, value):
            return state.run(self, 2, value)

        def label(self, name):
            return state.run(self, 3, name)

        def finalize(self):
            return state.run(self, 4)

        @property
        def offset(self):
            return state.run(self, 5)

        def _reg(self, value):
            return state.run(self, 6, value)

    return _code_call_names(SelectedStateCode)


def installed_machine_state(manifest_path):
    return _installed_json_image(manifest_path, SOURCE, SCHEMA, NativeMachineState)

"""Small, deterministic x86-64 encoder used by the direct HIA backend.

The supported instructions are encoded here as bytes. No assembler, LLVM or
other code generator is invoked. This is an implementation, not an ISA proof;
the executable/disassembly tests check its admitted instruction surface.
"""
from __future__ import annotations

from contextlib import contextmanager
from contextvars import ContextVar
import os
import re
import struct

_REGISTERS = {name: i for i, name in enumerate((
    "rax", "rcx", "rdx", "rbx", "rsp", "rbp", "rsi", "rdi",
    "r8", "r9", "r10", "r11", "r12", "r13", "r14", "r15"))}
_CONDITIONS = {
    "o": 0, "no": 1, "b": 2, "c": 2, "nae": 2,
    "ae": 3, "nb": 3, "nc": 3, "e": 4, "z": 4,
    "ne": 5, "nz": 5, "be": 6, "na": 6, "a": 7, "nbe": 7,
    "s": 8, "ns": 9, "p": 10, "pe": 10, "np": 11, "po": 11,
    "l": 12, "nge": 12, "ge": 13, "nl": 13, "le": 14,
    "ng": 14, "g": 15, "nle": 15,
}
_SYMBOL = re.compile(r"[A-Za-z_][A-Za-z_0-9]{0,191}\Z")
MAX_CODE_BYTES = 64 * 1024 * 1024


_UNSELECTED = object()
_NATIVE_OWNER = ContextVar('hia_machine_encoding_native_owner', default=_UNSELECTED)
_NATIVE_SELECTOR = 'HEPTA_HIA_MACHINE_ENCODING_MANIFEST'
_NATIVE_STATE_OWNER = ContextVar('hia_machine_state_native_owner', default=_UNSELECTED)
_NATIVE_STATE_SELECTOR = 'HEPTA_HIA_MACHINE_STATE_MANIFEST'
_NATIVE_INSTRUCTION_OWNER = ContextVar('hia_machine_instructions_native_owner', default=_UNSELECTED)
_NATIVE_INSTRUCTION_SELECTOR = 'HEPTA_HIA_MACHINE_INSTRUCTIONS_MANIFEST'


def _selected_owner():
    owner = _NATIVE_OWNER.get()
    if owner is not _UNSELECTED:
        return owner
    path = os.environ.get(_NATIVE_SELECTOR)
    if not path:
        return None
    from .hia_machine_encoding_native import installed_machine_encoding
    return installed_machine_encoding(path)


def _selected_state_owner(encoding):
    state = _NATIVE_STATE_OWNER.get()
    if state is not _UNSELECTED:
        return state
    path = os.environ.get(_NATIVE_STATE_SELECTOR)
    if not path:
        return None
    if encoding is None:
        raise MachineEncodingError('native Code state requires the native instruction byte owner')
    from .hia_machine_state_native import installed_machine_state
    return installed_machine_state(path)


def _selected_instruction_owner(encoding, state):
    owner = _NATIVE_INSTRUCTION_OWNER.get()
    if owner is not _UNSELECTED:
        return owner
    path = os.environ.get(_NATIVE_INSTRUCTION_SELECTOR)
    if not path:
        return None
    if encoding is None or state is None:
        raise MachineEncodingError('native instruction control requires native Code state and instruction bytes')
    from .hia_machine_instructions_native import installed_machine_instructions
    return installed_machine_instructions(path)


@contextmanager
def native_encoding_scope():
    """Pin one explicit selection, including no selection, across a whole emit."""
    owner = _selected_owner()
    state = _selected_state_owner(owner)
    instructions = _selected_instruction_owner(owner, state)
    previous = (_NATIVE_OWNER.get(), _NATIVE_STATE_OWNER.get(),
                _NATIVE_INSTRUCTION_OWNER.get())
    try:
        # Preserve the actual previous values even if set() completed but an
        # interruption loses its returned token before Python can store it.
        _NATIVE_OWNER.set(owner)
        _NATIVE_STATE_OWNER.set(state)
        _NATIVE_INSTRUCTION_OWNER.set(instructions)
        yield
    finally:
        try:
            _NATIVE_INSTRUCTION_OWNER.set(previous[2])
        finally:
            try:
                _NATIVE_STATE_OWNER.set(previous[1])
            finally:
                _NATIVE_OWNER.set(previous[0])


def native_implementation_identity():
    owner = _selected_owner()
    state = _selected_state_owner(owner)
    instructions = _selected_instruction_owner(owner, state)
    if owner is None:
        return b''
    from hashlib import sha256
    from .hia_machine_encoding_native import SOURCE
    def admitted_identity(image, source):
        source_sha = sha256(source.read_bytes()).hexdigest()
        admitted = image.admitted_source_sha256
        if type(admitted) is not str or source_sha != admitted:
            raise ValueError('native HIA machine source identity mismatch')
        return source_sha + ':' + image.image_sha256
    identity = admitted_identity(owner, SOURCE)
    if state is not None:
        from .hia_machine_state_native import SOURCE as STATE_SOURCE
        identity += ':machine-state:' + admitted_identity(state, STATE_SOURCE)
    if instructions is not None:
        from .hia_machine_instructions_native import SOURCE as INSTRUCTION_SOURCE
        identity += ':machine-instructions:' + admitted_identity(instructions, INSTRUCTION_SOURCE)
    return identity.encode('ascii')


class MachineEncodingError(ValueError):
    """An operand cannot be represented by the admitted x86-64 profile."""


def _reg(value):
    if type(value) is not str or value not in _REGISTERS:
        raise MachineEncodingError("unknown x86-64 register")
    return _REGISTERS[value]


def _s32(value):
    if type(value) is not int or not -(1 << 31) <= value < 1 << 31:
        raise MachineEncodingError("operand is outside signed disp32/imm32")
    return struct.pack("<i", value)


def _condition(value):
    if type(value) is not str or value not in _CONDITIONS:
        raise MachineEncodingError("unknown x86-64 condition")
    return _CONDITIONS[value]


class Code:
    """One .text image with bounded rel32 labels and symbol call relocations.

    Operands are register names. All ordinary arithmetic uses 64 bits. Every
    memory address uses an explicit base and signed displacement, with no
    implicit indexed addressing. ``finalize`` does not mutate the image and
    therefore produces identical bytes on repeated calls.
    """

    def __new__(cls, *args, **kwargs):
        # Existing subclasses keep their own virtual instruction methods.
        # Only an ordinary Code construction selects this explicit byte owner.
        if cls is Code:
            owner = _selected_owner()
            state = _selected_state_owner(owner)
            instructions = _selected_instruction_owner(owner, state)
            if owner is not None:
                from .hia_machine_encoding_native import selected_code_class
                return object.__new__(selected_code_class(owner, state, instructions))
        return object.__new__(cls)

    def __init__(self, *, scratch_registers=None, move_immediate="movabs", alu_immediate="imm32"):
        # Both registers are explicit scratch operands, never implicit ISA or
        # SysV argument/result registers. Only a complete bijection is admitted.
        mapping = {"r10": "r10", "r11": "r11"} if scratch_registers is None else scratch_registers
        if (type(mapping) is not dict or set(mapping) != {"r10", "r11"}
                or any(type(value) is not str for value in mapping.values())
                or set(mapping.values()) != {"r10", "r11"}):
            raise MachineEncodingError("scratch registers must bijectively rename r10/r11")
        if type(move_immediate) is not str or move_immediate not in {"movabs", "mov32_if_exact"}:
            raise MachineEncodingError("unreviewed immediate move selection")
        if type(alu_immediate) is not str or alu_immediate not in {"imm32", "imm8_if_exact"}:
            raise MachineEncodingError("unreviewed immediate arithmetic selection")
        self.scratch_registers = dict(mapping)
        self.move_immediate, self.alu_immediate = move_immediate, alu_immediate
        self.data = bytearray()
        self.labels = {}
        self.fixups = []
        self.relocations = []

    def _reg(self, value):
        # Check type first so malformed/unhashable operands retain typed errors.
        if type(value) is not str:
            raise MachineEncodingError("unknown x86-64 register")
        return _reg(self.scratch_registers.get(value, value))

    def align(self, boundary):
        if type(boundary) is not int or boundary not in {1, 16, 32, 64}:
            raise MachineEncodingError("unreviewed function alignment")
        self.emit(b"\x90" * ((-len(self.data)) % boundary))

    @property
    def offset(self):
        return len(self.data)

    def emit(self, value):
        if type(value) not in (bytes, bytearray):
            raise MachineEncodingError("encoded instructions must be bytes")
        if len(value) > MAX_CODE_BYTES - len(self.data):
            raise MachineEncodingError("x86-64 image exceeds code byte limit")
        self.data.extend(value)

    def _rr(self, opcode, reg, rm, *, wide=True):
        r, m = self._reg(reg), self._reg(rm)
        rex = 0x40 | (8 if wide else 0) | ((r >> 3) << 2) | (m >> 3)
        self.emit(bytes([rex]) + opcode + bytes([0xc0 | ((r & 7) << 3) | (m & 7)]))

    def _mem(self, opcode, reg, base, disp=0, *, wide=True):
        r, b = self._reg(reg), self._reg(base)
        displacement = _s32(disp)
        rex = 0x40 | (8 if wide else 0) | ((r >> 3) << 2) | (b >> 3)
        modrm = 0x80 | ((r & 7) << 3) | (b & 7)
        sib = b"\x24" if b & 7 == 4 else b""
        self.emit(bytes([rex]) + opcode + bytes([modrm]) + sib + displacement)

    def label(self, name):
        if type(name) is not str or not name or len(name) > 512 or name in self.labels:
            raise MachineEncodingError("empty, oversized or duplicate machine label")
        self.labels[name] = len(self.data)

    def _branch(self, prefix, target):
        if type(target) is not str or not target or len(target) > 512:
            raise MachineEncodingError("invalid branch target")
        self.emit(prefix)
        self.fixups.append((len(self.data), target))
        self.emit(b"\0" * 4)

    def jmp(self, target):
        self._branch(b"\xe9", target)

    def jcc(self, condition, target):
        self._branch(bytes([0x0f, 0x80 + _condition(condition)]), target)

    def call(self, symbol):
        if type(symbol) is not str or _SYMBOL.fullmatch(symbol) is None:
            raise MachineEncodingError("invalid call symbol")
        self.emit(b"\xe8")
        self.relocations.append({"offset": len(self.data), "symbol": symbol,
                                 "type": 4, "addend": -4})
        self.emit(b"\0" * 4)

    def mov_rr(self, dst, src):
        self._rr(b"\x89", src, dst)

    def mov_imm(self, dst, value):
        reg = self._reg(dst)
        if type(value) is not int or not -(1 << 63) <= value < 1 << 64:
            raise MachineEncodingError("immediate is outside the 64-bit word")
        if self.move_immediate == "mov32_if_exact" and 0 <= value < 1 << 32:
            # A 32-bit destination write zero-extends and MOV leaves flags alone.
            prefix = b"\x41" if reg >= 8 else b""
            self.emit(prefix + bytes([0xb8 + (reg & 7)]) + struct.pack("<I", value))
        else:
            self.emit(bytes([0x48 | (reg >> 3), 0xb8 + (reg & 7)]) +
                      struct.pack("<Q", value & ((1 << 64) - 1)))

    def load(self, dst, base, disp=0):
        self._mem(b"\x8b", dst, base, disp)

    def store(self, base, disp, src):
        self._mem(b"\x89", src, base, disp)

    def lea(self, dst, base, disp=0):
        self._mem(b"\x8d", dst, base, disp)

    def load_u8(self, dst, base, disp=0):
        self._mem(b"\x0f\xb6", dst, base, disp)

    def store_u8(self, base, disp, src):
        # Even low registers 4..7 need a REX prefix to name spl/bpl/sil/dil.
        self._mem(b"\x88", src, base, disp, wide=False)

    def add(self, dst, src): self._rr(b"\x01", src, dst)
    def sub(self, dst, src): self._rr(b"\x29", src, dst)
    def and_(self, dst, src): self._rr(b"\x21", src, dst)
    def or_(self, dst, src): self._rr(b"\x09", src, dst)
    def xor(self, dst, src): self._rr(b"\x31", src, dst)
    def cmp(self, left, right): self._rr(b"\x39", right, left)
    def test(self, left, right): self._rr(b"\x85", right, left)

    def alu_imm(self, op, dst, value):
        groups = {"add": 0, "or": 1, "and": 4, "sub": 5, "xor": 6, "cmp": 7}
        if type(op) is not str or op not in groups:
            raise MachineEncodingError("unsupported immediate ALU operation")
        r = self._reg(dst)
        immediate = _s32(value)
        compact = self.alu_immediate == "imm8_if_exact" and -128 <= value <= 127
        if compact:
            immediate = struct.pack("<b", value)
        self.emit(bytes([0x48 | (r >> 3), 0x83 if compact else 0x81,
                         0xc0 | (groups[op] << 3) | (r & 7)]) + immediate)

    def shift(self, op, dst, count):
        groups = {"shl": 4, "shr": 5, "sar": 7}
        if type(op) is not str or op not in groups:
            raise MachineEncodingError("unsupported shift operation")
        r = self._reg(dst)
        prefix = bytes([0x48 | (r >> 3)])
        modrm = bytes([0xc0 | (groups[op] << 3) | (r & 7)])
        if count == "cl":
            self.emit(prefix + b"\xd3" + modrm)
        elif type(count) is int and 0 <= count < 64:
            self.emit(prefix + b"\xc1" + modrm + bytes([count]))
        else:
            raise MachineEncodingError("shift count must be 0..63 or cl")

    def shift_imm(self, op, dst, count): self.shift(op, dst, count)
    def shift_cl(self, op, dst): self.shift(op, dst, "cl")

    def shl(self, dst, count): self.shift("shl", dst, count)
    def shr(self, dst, count): self.shift("shr", dst, count)
    def sar(self, dst, count): self.shift("sar", dst, count)

    def imul(self, dst, src):
        self._rr(b"\x0f\xaf", dst, src)

    def imul_rr(self, dst, src): self.imul(dst, src)

    def _unary(self, group, src):
        r = self._reg(src)
        self.emit(bytes([0x48 | (r >> 3), 0xf7, 0xc0 | (group << 3) | (r & 7)]))

    def mul(self, src): self._unary(4, src)
    def imul_full(self, src): self._unary(5, src)
    def div(self, src): self._unary(6, src)
    def idiv(self, src): self._unary(7, src)
    def neg(self, src): self._unary(3, src)
    def bitnot(self, src): self._unary(2, src)
    def cqo(self): self.emit(b"\x48\x99")

    def setcc(self, condition, dst):
        condition = _condition(condition)
        r = self._reg(dst)
        # MOV preserves flags; this creates the canonical zero-extended bool.
        self.mov_imm(dst, 0)
        self.emit(bytes([0x40 | (r >> 3), 0x0f, 0x90 + condition, 0xc0 | (r & 7)]))

    def cmov(self, condition, dst, src):
        # The reviewed form has register operands only. It preserves flags and
        # cannot introduce a speculative memory access to an unselected input.
        self._rr(bytes([0x0f, 0x40 + _condition(condition)]), dst, src)

    def push(self, reg):
        r = self._reg(reg)
        self.emit((b"\x41" if r >= 8 else b"") + bytes([0x50 + (r & 7)]))

    def pop(self, reg):
        r = self._reg(reg)
        self.emit((b"\x41" if r >= 8 else b"") + bytes([0x58 + (r & 7)]))

    def ret(self): self.emit(b"\xc3")
    def leave(self): self.emit(b"\xc9")
    def ud2(self): self.emit(b"\x0f\x0b")

    def finalize(self):
        if len(self.data) > MAX_CODE_BYTES:
            raise MachineEncodingError("x86-64 image exceeds code byte limit")
        result = bytearray(self.data)
        for offset, target in self.fixups:
            if target not in self.labels:
                raise MachineEncodingError("unresolved machine label: " + target)
            result[offset:offset + 4] = _s32(self.labels[target] - (offset + 4))
        return bytes(result), [dict(row) for row in self.relocations]

"""Explicitly selected bridge for HIA-owned x86-64 instruction bytes.

Python still owns public operand admission, mutable Code storage, labels,
relocations, method dispatch and foreign effects. Every generated instruction
byte in NativeEncodedCode's public instruction methods comes from HIA.
This byte owner is not a complete backend, default activation or release gate.
"""
from __future__ import annotations

from collections import Counter
import ctypes
from functools import lru_cache
import struct

from hepta import hia_machine_x64 as reference
from hepta.hia_json_preflight_native import (
    NativeHiaJsonImage, _installed_json_image, _source_resource_path)

SOURCE = _source_resource_path("examples/hia_bootstrap/machine_encoding.hiaasm")
SCHEMA = "hepta.hia.machine-encoding-native.v2"
SELECTOR = "HEPTA_HIA_MACHINE_ENCODING_MANIFEST"

COMMANDS = (
    'align', 'mov_rr', 'mov_imm', 'load', 'store', 'lea', 'load_u8', 'store_u8',
    'add', 'sub', 'and_', 'or_', 'xor', 'cmp', 'test', 'alu_imm', 'shift',
    'imul', 'mul', 'imul_full', 'div', 'idiv', 'neg', 'bitnot', 'cqo',
    'set_byte', 'cmov', 'push', 'pop', 'ret', 'leave', 'ud2',
    'jmp_prefix', 'jcc_prefix', 'call_prefix', 'zero_rel32', 'rel32',
)
COMMAND_IDS = {name: index for index, name in enumerate(COMMANDS, 1)}
MAGIC = int.from_bytes(b'HIAX6402', 'little')
MASK = (1 << 64) - 1


class NativeMachineEncoding(NativeHiaJsonImage):
    def __init__(self, image, expected_sha256):
        super().__init__(image, expected_sha256)
        self.calls = Counter()

    def encode(self, command, *, r=0, m=0, value=0, auxiliary=0, mode=0, offset=0):
        packet = struct.pack('<8Q', MAGIC, COMMAND_IDS[command], r, m,
                             value & MASK, auxiliary, mode, offset)
        source = ctypes.create_string_buffer(packet, len(packet))
        output = ctypes.create_string_buffer(b'\xa5' * 80, 80)
        workspace = ctypes.create_string_buffer(b'\x5a' * 8, 8)
        status = self._entry(source, len(packet), output, 80, workspace, 8)
        self.calls[command] += 1
        if status != 0:
            raise RuntimeError('native machine encoding packet refused: ' + hex(status))
        length, = struct.unpack_from('<Q', output)
        cursor, = struct.unpack_from('<Q', workspace)
        if (length > 63 or cursor != length + 8 or source.raw != packet
                or output.raw[8 + length:] != b'\xa5' * (72 - length)):
            raise RuntimeError('native machine encoding output contract differs')
        return output.raw[8:8 + length]


def _displacement(value):
    # Public operand admission is deliberately still a hosted boundary. Do not
    # call the retained struct-packing helper merely to validate an operand.
    if type(value) is not int or not -(1 << 31) <= value < 1 << 31:
        raise reference.MachineEncodingError('operand is outside signed disp32/imm32')
    return value


class NativeEncodedCode(reference.Code):
    """Code-compatible byte owner; mutable host state and operand admission remain hosted."""
    def __init__(self, encoding, *, scratch_registers=None,
                 move_immediate='movabs', alu_immediate='imm32'):
        super().__init__(scratch_registers=scratch_registers,
                         move_immediate=move_immediate, alu_immediate=alu_immediate)
        self.encoding = encoding

    def _bytes(self, command, **values):
        return self.encoding.encode(command, **values)

    def align(self, boundary):
        if type(boundary) is not int or boundary not in {1, 16, 32, 64}:
            raise reference.MachineEncodingError('unreviewed function alignment')
        self.emit(self._bytes('align', auxiliary=boundary, offset=len(self.data)))

    def _pair(self, command, dst, src, *, destination_first=False):
        if destination_first:
            destination, source = self._reg(dst), self._reg(src)
        else:
            source, destination = self._reg(src), self._reg(dst)
        self.emit(self._bytes(command, r=destination, m=source))

    def mov_rr(self, dst, src):
        self._pair('mov_rr', dst, src)

    def mov_imm(self, dst, value):
        register = self._reg(dst)
        if type(value) is not int or not -(1 << 63) <= value < 1 << 64:
            raise reference.MachineEncodingError('immediate is outside the 64-bit word')
        mode = bool(self.move_immediate == 'mov32_if_exact')
        self.emit(self._bytes('mov_imm', r=register, value=value, mode=int(mode)))

    def _memory(self, command, reg, base, disp):
        register, address = self._reg(reg), self._reg(base)
        value = _displacement(disp)
        self.emit(self._bytes(command, r=register, m=address, value=value))

    def load(self, dst, base, disp=0):
        self._memory('load', dst, base, disp)

    def store(self, base, disp, src):
        self._memory('store', src, base, disp)

    def lea(self, dst, base, disp=0):
        self._memory('lea', dst, base, disp)

    def load_u8(self, dst, base, disp=0):
        self._memory('load_u8', dst, base, disp)

    def store_u8(self, base, disp, src):
        self._memory('store_u8', src, base, disp)

    def add(self, dst, src): self._pair('add', dst, src)
    def sub(self, dst, src): self._pair('sub', dst, src)
    def and_(self, dst, src): self._pair('and_', dst, src)
    def or_(self, dst, src): self._pair('or_', dst, src)
    def xor(self, dst, src): self._pair('xor', dst, src)
    def cmp(self, left, right): self._pair('cmp', left, right)
    def test(self, left, right): self._pair('test', left, right)

    def alu_imm(self, op, dst, value):
        choices = {'add': 0, 'or': 1, 'and': 2, 'sub': 3, 'xor': 4, 'cmp': 5}
        if type(op) is not str or op not in choices:
            raise reference.MachineEncodingError('unsupported immediate ALU operation')
        register = self._reg(dst)
        value = _displacement(value)
        # A foreign option can return a falsy object, retained by `and`.
        # Preserve all three original truth observations, the intervening
        # signed-byte refusal, and binding emit before the third observation.
        compact = self.alu_immediate == 'imm8_if_exact' and -128 <= value <= 127
        short_word = False
        if compact:
            if not -128 <= value <= 127:
                # This branch cannot produce a byte. Preserve the host runtime's
                # exact rejection object/message; admitted instruction bytes
                # are still produced only by HIA below.
                struct.pack('<b', value)
            short_word = True
        emit = self.emit
        short_opcode = bool(compact)
        emit(self._bytes('alu_imm', r=register, value=value,
                         auxiliary=choices[op], mode=int(short_opcode), offset=int(short_word)))

    def shift(self, op, dst, count):
        choices = {'shl': 0, 'shr': 1, 'sar': 2}
        if type(op) is not str or op not in choices:
            raise reference.MachineEncodingError('unsupported shift operation')
        register = self._reg(dst)
        if count == 'cl':
            self.emit(self._bytes('shift', r=register, auxiliary=choices[op], mode=1))
        elif type(count) is int and 0 <= count < 64:
            self.emit(self._bytes('shift', r=register, value=count, auxiliary=choices[op]))
        else:
            raise reference.MachineEncodingError('shift count must be 0..63 or cl')

    def shift_imm(self, op, dst, count): self.shift(op, dst, count)
    def shift_cl(self, op, dst): self.shift(op, dst, 'cl')
    def shl(self, dst, count): self.shift('shl', dst, count)
    def shr(self, dst, count): self.shift('shr', dst, count)
    def sar(self, dst, count): self.shift('sar', dst, count)

    def imul(self, dst, src):
        self._pair('imul', dst, src, destination_first=True)

    def imul_rr(self, dst, src): self.imul(dst, src)

    def _one(self, command, value):
        register = self._reg(value)
        self.emit(self._bytes(command, r=register))

    def mul(self, src): self._one('mul', src)
    def imul_full(self, src): self._one('imul_full', src)
    def div(self, src): self._one('div', src)
    def idiv(self, src): self._one('idiv', src)
    def neg(self, src): self._one('neg', src)
    def bitnot(self, src): self._one('bitnot', src)
    def cqo(self): self.emit(self._bytes('cqo'))

    def setcc(self, condition, dst):
        condition = reference._condition(condition)
        register = self._reg(dst)
        # Keep the original second register observation inside mov_imm. A
        # foreign mapping can change between that observation and SETcc.
        self.mov_imm(dst, 0)
        self.emit(self._bytes('set_byte', r=register, auxiliary=condition))

    def cmov(self, condition, dst, src):
        condition = reference._condition(condition)
        destination, source = self._reg(dst), self._reg(src)
        self.emit(self._bytes('cmov', r=destination, m=source, auxiliary=condition))

    def push(self, reg): self._one('push', reg)
    def pop(self, reg): self._one('pop', reg)
    def ret(self): self.emit(self._bytes('ret'))
    def leave(self): self.emit(self._bytes('leave'))
    def ud2(self): self.emit(self._bytes('ud2'))

    def _branch_bytes(self, prefix, target):
        if type(target) is not str or not target or len(target) > 512:
            raise reference.MachineEncodingError('invalid branch target')
        self.emit(prefix)
        self.fixups.append((len(self.data), target))
        self.emit(self._bytes('zero_rel32'))

    def jmp(self, target):
        self._branch_bytes(self._bytes('jmp_prefix'), target)

    def jcc(self, condition, target):
        condition = reference._condition(condition)
        self._branch_bytes(self._bytes('jcc_prefix', auxiliary=condition), target)

    def call(self, symbol):
        if type(symbol) is not str or reference._SYMBOL.fullmatch(symbol) is None:
            raise reference.MachineEncodingError('invalid call symbol')
        self.emit(self._bytes('call_prefix'))
        self.relocations.append({'offset': len(self.data), 'symbol': symbol, 'type': 4, 'addend': -4})
        self.emit(self._bytes('zero_rel32'))

    def finalize(self):
        if len(self.data) > reference.MAX_CODE_BYTES:
            raise reference.MachineEncodingError('x86-64 image exceeds code byte limit')
        result = bytearray(self.data)
        for offset, target in self.fixups:
            if target not in self.labels:
                raise reference.MachineEncodingError('unresolved machine label: ' + target)
            value = _displacement(self.labels[target] - (offset + 4))
            result[offset:offset + 4] = self._bytes('rel32', value=value)
        return bytes(result), [dict(row) for row in self.relocations]


@lru_cache(maxsize=3)
def selected_code_class(encoding, state=None):
    if state is not None:
        from .hia_machine_state_native import selected_state_code_class
        return selected_state_code_class(encoding, state)
    class SelectedCode(NativeEncodedCode):
        def __init__(self, *, scratch_registers=None,
                     move_immediate='movabs', alu_immediate='imm32'):
            super().__init__(encoding, scratch_registers=scratch_registers,
                             move_immediate=move_immediate, alu_immediate=alu_immediate)
    return SelectedCode


def installed_machine_encoding(manifest_path):
    """Bind immutable image bytes to the package-owned HIA source on every selection."""
    return _installed_json_image(manifest_path, SOURCE, SCHEMA, NativeMachineEncoding)

"""Small, deterministic x86-64 encoder used by the direct HIA backend.

The supported instructions are encoded here as bytes. No assembler, LLVM or
other code generator is invoked. This is an implementation, not an ISA proof;
the executable/disassembly tests check its admitted instruction surface.
"""
from __future__ import annotations

import re
import struct

_REGISTERS = {name: i for i, name in enumerate((
    "rax", "rcx", "rdx", "rbx", "rsp", "rbp", "rsi", "rdi",
    "r8", "r9", "r10", "r11", "r12", "r13", "r14", "r15"))}
_CONDITIONS = {
    "o": 0, "no": 1, "b": 2, "c": 2, "nae": 2,
    "ae": 3, "nb": 3, "nc": 3, "e": 4, "z": 4,
    "ne": 5, "nz": 5, "be": 6, "na": 6, "a": 7, "nbe": 7,
    "s": 8, "ns": 9, "p": 10, "pe": 10, "np": 11, "po": 11,
    "l": 12, "nge": 12, "ge": 13, "nl": 13, "le": 14,
    "ng": 14, "g": 15, "nle": 15,
}
_SYMBOL = re.compile(r"[A-Za-z_][A-Za-z_0-9]{0,191}\Z")
MAX_CODE_BYTES = 64 * 1024 * 1024


class MachineEncodingError(ValueError):
    """An operand cannot be represented by the admitted x86-64 profile."""


def _reg(value):
    if type(value) is not str or value not in _REGISTERS:
        raise MachineEncodingError("unknown x86-64 register")
    return _REGISTERS[value]


def _s32(value):
    if type(value) is not int or not -(1 << 31) <= value < 1 << 31:
        raise MachineEncodingError("operand is outside signed disp32/imm32")
    return struct.pack("<i", value)


def _condition(value):
    if type(value) is not str or value not in _CONDITIONS:
        raise MachineEncodingError("unknown x86-64 condition")
    return _CONDITIONS[value]


class Code:
    """One .text image with bounded rel32 labels and symbol call relocations.

    Operands are register names. All ordinary arithmetic uses 64 bits. Every
    memory address uses an explicit base and signed displacement, with no
    implicit indexed addressing. ``finalize`` does not mutate the image and
    therefore produces identical bytes on repeated calls.
    """

    def __init__(self, *, scratch_registers=None, move_immediate="movabs", alu_immediate="imm32"):
        # Both registers are explicit scratch operands, never implicit ISA or
        # SysV argument/result registers. Only a complete bijection is admitted.
        mapping = {"r10": "r10", "r11": "r11"} if scratch_registers is None else scratch_registers
        if (type(mapping) is not dict or set(mapping) != {"r10", "r11"}
                or any(type(value) is not str for value in mapping.values())
                or set(mapping.values()) != {"r10", "r11"}):
            raise MachineEncodingError("scratch registers must bijectively rename r10/r11")
        if type(move_immediate) is not str or move_immediate not in {"movabs", "mov32_if_exact"}:
            raise MachineEncodingError("unreviewed immediate move selection")
        if type(alu_immediate) is not str or alu_immediate not in {"imm32", "imm8_if_exact"}:
            raise MachineEncodingError("unreviewed immediate arithmetic selection")
        self.scratch_registers = dict(mapping)
        self.move_immediate, self.alu_immediate = move_immediate, alu_immediate
        self.data = bytearray()
        self.labels = {}
        self.fixups = []
        self.relocations = []

    def _reg(self, value):
        # Check type first so malformed/unhashable operands retain typed errors.
        if type(value) is not str:
            raise MachineEncodingError("unknown x86-64 register")
        return _reg(self.scratch_registers.get(value, value))

    def align(self, boundary):
        if type(boundary) is not int or boundary not in {1, 16, 32, 64}:
            raise MachineEncodingError("unreviewed function alignment")
        self.emit(b"\x90" * ((-len(self.data)) % boundary))

    @property
    def offset(self):
        return len(self.data)

    def emit(self, value):
        if type(value) not in (bytes, bytearray):
            raise MachineEncodingError("encoded instructions must be bytes")
        if len(value) > MAX_CODE_BYTES - len(self.data):
            raise MachineEncodingError("x86-64 image exceeds code byte limit")
        self.data.extend(value)

    def _rr(self, opcode, reg, rm, *, wide=True):
        r, m = self._reg(reg), self._reg(rm)
        rex = 0x40 | (8 if wide else 0) | ((r >> 3) << 2) | (m >> 3)
        self.emit(bytes([rex]) + opcode + bytes([0xc0 | ((r & 7) << 3) | (m & 7)]))

    def _mem(self, opcode, reg, base, disp=0, *, wide=True):
        r, b = self._reg(reg), self._reg(base)
        displacement = _s32(disp)
        rex = 0x40 | (8 if wide else 0) | ((r >> 3) << 2) | (b >> 3)
        modrm = 0x80 | ((r & 7) << 3) | (b & 7)
        sib = b"\x24" if b & 7 == 4 else b""
        self.emit(bytes([rex]) + opcode + bytes([modrm]) + sib + displacement)

    def label(self, name):
        if type(name) is not str or not name or len(name) > 512 or name in self.labels:
            raise MachineEncodingError("empty, oversized or duplicate machine label")
        self.labels[name] = len(self.data)

    def _branch(self, prefix, target):
        if type(target) is not str or not target or len(target) > 512:
            raise MachineEncodingError("invalid branch target")
        self.emit(prefix)
        self.fixups.append((len(self.data), target))
        self.emit(b"\0" * 4)

    def jmp(self, target):
        self._branch(b"\xe9", target)

    def jcc(self, condition, target):
        self._branch(bytes([0x0f, 0x80 + _condition(condition)]), target)

    def call(self, symbol):
        if type(symbol) is not str or _SYMBOL.fullmatch(symbol) is None:
            raise MachineEncodingError("invalid call symbol")
        self.emit(b"\xe8")
        self.relocations.append({"offset": len(self.data), "symbol": symbol,
                                 "type": 4, "addend": -4})
        self.emit(b"\0" * 4)

    def mov_rr(self, dst, src):
        self._rr(b"\x89", src, dst)

    def mov_imm(self, dst, value):
        reg = self._reg(dst)
        if type(value) is not int or not -(1 << 63) <= value < 1 << 64:
            raise MachineEncodingError("immediate is outside the 64-bit word")
        if self.move_immediate == "mov32_if_exact" and 0 <= value < 1 << 32:
            # A 32-bit destination write zero-extends and MOV leaves flags alone.
            prefix = b"\x41" if reg >= 8 else b""
            self.emit(prefix + bytes([0xb8 + (reg & 7)]) + struct.pack("<I", value))
        else:
            self.emit(bytes([0x48 | (reg >> 3), 0xb8 + (reg & 7)]) +
                      struct.pack("<Q", value & ((1 << 64) - 1)))

    def load(self, dst, base, disp=0):
        self._mem(b"\x8b", dst, base, disp)

    def store(self, base, disp, src):
        self._mem(b"\x89", src, base, disp)

    def lea(self, dst, base, disp=0):
        self._mem(b"\x8d", dst, base, disp)

    def load_u8(self, dst, base, disp=0):
        self._mem(b"\x0f\xb6", dst, base, disp)

    def store_u8(self, base, disp, src):
        # Even low registers 4..7 need a REX prefix to name spl/bpl/sil/dil.
        self._mem(b"\x88", src, base, disp, wide=False)

    def add(self, dst, src): self._rr(b"\x01", src, dst)
    def sub(self, dst, src): self._rr(b"\x29", src, dst)
    def and_(self, dst, src): self._rr(b"\x21", src, dst)
    def or_(self, dst, src): self._rr(b"\x09", src, dst)
    def xor(self, dst, src): self._rr(b"\x31", src, dst)
    def cmp(self, left, right): self._rr(b"\x39", right, left)
    def test(self, left, right): self._rr(b"\x85", right, left)

    def alu_imm(self, op, dst, value):
        groups = {"add": 0, "or": 1, "and": 4, "sub": 5, "xor": 6, "cmp": 7}
        if type(op) is not str or op not in groups:
            raise MachineEncodingError("unsupported immediate ALU operation")
        r = self._reg(dst)
        immediate = _s32(value)
        compact = self.alu_immediate == "imm8_if_exact" and -128 <= value <= 127
        if compact:
            immediate = struct.pack("<b", value)
        self.emit(bytes([0x48 | (r >> 3), 0x83 if compact else 0x81,
                         0xc0 | (groups[op] << 3) | (r & 7)]) + immediate)

    def shift(self, op, dst, count):
        groups = {"shl": 4, "shr": 5, "sar": 7}
        if type(op) is not str or op not in groups:
            raise MachineEncodingError("unsupported shift operation")
        r = self._reg(dst)
        prefix = bytes([0x48 | (r >> 3)])
        modrm = bytes([0xc0 | (groups[op] << 3) | (r & 7)])
        if count == "cl":
            self.emit(prefix + b"\xd3" + modrm)
        elif type(count) is int and 0 <= count < 64:
            self.emit(prefix + b"\xc1" + modrm + bytes([count]))
        else:
            raise MachineEncodingError("shift count must be 0..63 or cl")

    def shift_imm(self, op, dst, count): self.shift(op, dst, count)
    def shift_cl(self, op, dst): self.shift(op, dst, "cl")

    def shl(self, dst, count): self.shift("shl", dst, count)
    def shr(self, dst, count): self.shift("shr", dst, count)
    def sar(self, dst, count): self.shift("sar", dst, count)

    def imul(self, dst, src):
        self._rr(b"\x0f\xaf", dst, src)

    def imul_rr(self, dst, src): self.imul(dst, src)

    def _unary(self, group, src):
        r = self._reg(src)
        self.emit(bytes([0x48 | (r >> 3), 0xf7, 0xc0 | (group << 3) | (r & 7)]))

    def mul(self, src): self._unary(4, src)
    def imul_full(self, src): self._unary(5, src)
    def div(self, src): self._unary(6, src)
    def idiv(self, src): self._unary(7, src)
    def neg(self, src): self._unary(3, src)
    def bitnot(self, src): self._unary(2, src)
    def cqo(self): self.emit(b"\x48\x99")

    def setcc(self, condition, dst):
        condition = _condition(condition)
        r = self._reg(dst)
        # MOV preserves flags; this creates the canonical zero-extended bool.
        self.mov_imm(dst, 0)
        self.emit(bytes([0x40 | (r >> 3), 0x0f, 0x90 + condition, 0xc0 | (r & 7)]))

    def cmov(self, condition, dst, src):
        # The reviewed form has register operands only. It preserves flags and
        # cannot introduce a speculative memory access to an unselected input.
        self._rr(bytes([0x0f, 0x40 + _condition(condition)]), dst, src)

    def push(self, reg):
        r = self._reg(reg)
        self.emit((b"\x41" if r >= 8 else b"") + bytes([0x50 + (r & 7)]))

    def pop(self, reg):
        r = self._reg(reg)
        self.emit((b"\x41" if r >= 8 else b"") + bytes([0x58 + (r & 7)]))

    def ret(self): self.emit(b"\xc3")
    def leave(self): self.emit(b"\xc9")
    def ud2(self): self.emit(b"\x0f\x0b")

    def finalize(self):
        if len(self.data) > MAX_CODE_BYTES:
            raise MachineEncodingError("x86-64 image exceeds code byte limit")
        result = bytearray(self.data)
        for offset, target in self.fixups:
            if target not in self.labels:
                raise MachineEncodingError("unresolved machine label: " + target)
            result[offset:offset + 4] = _s32(self.labels[target] - (offset + 4))
        return bytes(result), [dict(row) for row in self.relocations]

