        class Emit:
            def __call__(self,value):
                saved(value);code.emit=saved;events.append(['call',value.hex()]);return self
            def __del__(self):
                events.append(['del',len(code.data)]);code.label('from-del')
        code.emit=Emit();code.jmp('target')
