def register_number(n:u64, a:u64, b:u64, c:u64) -> u64:
    if a != 114:
        return 16
    if n == 2 and (b == 56 or b == 57):
        return b - 48
    if n != 3:
        return 16
    if b == 49 and c >= 48 and c <= 53:
        return c - 38
    if c == 120:
        if b == 97:
            return 0
        if b == 99:
            return 1
        if b == 100:
            return 2
        if b == 98:
            return 3
    if c == 112:
        if b == 115:
            return 4
        if b == 98:
            return 5
    if c == 105:
        if b == 115:
            return 6
        if b == 100:
            return 7
    return 16

